"use client";

import { useState } from "react";
import { Github, Sparkles } from "lucide-react";

interface RepoInputProps {
  onSubmit: (url: string) => void;
  isProcessing: boolean;
  recentRepos: {
    id: string;
    repo_url: string;
    repo_name: string;
  }[];
  onSelectRecentRepo: (url: string) => void;
}

export default function RepoInput({
  onSubmit,
  isProcessing,
  recentRepos,
  onSelectRecentRepo,
}: RepoInputProps) {
  const [url, setUrl] = useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (url.trim()) {
      onSubmit(url.trim());
    }
  };

  return (
    <div className="mx-auto flex w-full max-w-5xl flex-1 items-center justify-center">
      <div className="grid w-full gap-6 lg:grid-cols-[1.2fr_0.8fr]">
        <div className="rounded-3xl border border-white/10 bg-white/5 p-8 shadow-2xl backdrop-blur-xl">
          <div className="flex items-center gap-3 text-blue-300">
            <Sparkles className="h-5 w-5" />
            <span className="text-sm font-medium uppercase tracking-[0.25em]">
              Codebase Intelligence
            </span>
          </div>

          <h1 className="mt-5 text-4xl font-semibold text-white">
            Process a GitHub repo and start chatting with its code.
          </h1>
          <p className="mt-4 max-w-2xl text-sm leading-7 text-slate-300">
            Paste a public GitHub repository URL and RepoChat will clone,
            chunk, embed, and prepare it for question-answering.
          </p>

          <form onSubmit={handleSubmit} className="mt-8 flex flex-col gap-3 sm:flex-row">
            <div className="relative flex-1">
              <Github className="pointer-events-none absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-slate-500" />
              <input
                type="text"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="https://github.com/owner/repo"
                className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-12 pr-4 text-white outline-none transition focus:border-blue-400"
                disabled={isProcessing}
              />
            </div>
            <button
              type="submit"
              disabled={isProcessing || !url.trim()}
              className="rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 px-6 py-3 font-medium text-white shadow-lg shadow-blue-950/30 transition hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isProcessing ? "Processing..." : "Process Repo"}
            </button>
          </form>
          <p className="mt-4 text-sm text-slate-400">
            Public GitHub URLs work best, for example `https://github.com/vercel/next.js`.
          </p>
        </div>

        <div className="rounded-3xl border border-white/10 bg-slate-950/55 p-6 shadow-2xl backdrop-blur-xl">
          <h2 className="text-lg font-semibold text-white">Quick start from history</h2>
          <p className="mt-2 text-sm text-slate-400">
            Reprocess a repo from your saved history with one click.
          </p>
          <div className="mt-6 space-y-2">
            {recentRepos.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-white/10 px-4 py-6 text-sm text-slate-500">
                No saved repos yet. Process your first repository to populate this panel.
              </div>
            ) : (
              recentRepos.slice(0, 5).map((repo) => (
                <button
                  key={repo.id}
                  type="button"
                  onClick={() => onSelectRecentRepo(repo.repo_url)}
                  className="w-full rounded-2xl border border-transparent bg-white/5 px-4 py-3 text-left transition hover:border-white/10 hover:bg-white/10"
                >
                  <p className="truncate text-sm font-medium text-white">
                    {repo.repo_name}
                  </p>
                  <p className="mt-1 truncate text-xs text-slate-400">
                    {repo.repo_url}
                  </p>
                </button>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}